namespace ghidra.graph.algo.viewer;




using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using utility.function;

/**
 * Task monitor that will trigger a {@link #wait()} when {@link #checkCancelled()} is called.  This
 * allows clients to watch algorithms as they proceed.
 */
public class AlgorithmSteppingTaskMonitor : TaskMonitorAdapter {

	private Set<Callback> stepListeners = new();

	public AlgorithmSteppingTaskMonitor() {
		setCancelEnabled(true);
	}

	public void addStepListener(Callback c) {
		stepListeners.add(c);
	}

	/* @Override */
	public void cancel() {
		base.cancel();
		step(); // wake-up any waiting threads
	}

	/* @Override */
	public void checkCancelled()
    {

		base.checkCancelled();

		pause();
	}

	/**
	 * Causes this monitor to perform at {@link #wait()}.  Call {@link #step()} to allow the
	 * client to continue.
	 */
	public void pause() {

		if (isCancelled()) {
			return; // no pausing after cancelled
		}

		notifyStepReady();

		lock (this) {

			try {
				wait();
			}
			catch (InterruptedException e) {
				Msg.debug(this, "Interrupted waiting for next step", e);
			}

		}
	}

	public void step() {
		lock (this) {
			notify();
		}
	}

	protected void notifyStepReady() {
		stepListeners.forEach(l => l.call());
	}
}
